import { mapGetters, mapActions } from 'vuex';
import { SunMoon, Sun, Moon, Laptop, LayoutGrid, Palette, Images, Type, MessageSquareQuote, Coins, Megaphone, Mail, RotateCcw, Save, RefreshCw, CheckCircle2, AlertCircle, Sparkles } from 'lucide-vue-next';
export default {
  name: 'AdminSettings',
  components: {
    SunMoon,
    Sun,
    Moon,
    Laptop,
    LayoutGrid,
    Palette,
    Images,
    Type,
    MessageSquareQuote,
    Coins,
    Megaphone,
    Mail,
    RotateCcw,
    Save,
    RefreshCw,
    CheckCircle2,
    AlertCircle,
    Sparkles
  },
  data() {
    return {
      saving: false,
      statusMessage: '',
      statusType: 'success',
      form: {
        allowThemeToggle: true,
        themeMode: 'system',
        enableDesignSection: true,
        enableMultiPhotoUpload: true,
        enableCustomText: true,
        enableReviews: true,
        currencySymbol: '₹',
        deliveryFee: 100,
        freeDeliveryThreshold: 2000,
        announcementBanner: {
          enabled: false,
          text: ''
        },
        adminNotificationEmail: 'jaydeepsarkr@gmail.com',
        notifyAdminOnNewOrder: true,
        orderIdPrefix: 'PF'
      }
    };
  },
  computed: {
    ...mapGetters('settings', ['allSettings'])
  },
  mounted() {
    this.loadSettingsIntoForm();
  },
  methods: {
    ...mapActions('settings', ['fetchSettings', 'updateSettings', 'resetSettings']),
    loadSettingsIntoForm() {
      const current = this.allSettings || {};
      this.form = {
        allowThemeToggle: current.allowThemeToggle !== false,
        themeMode: current.themeMode || 'system',
        enableDesignSection: current.enableDesignSection !== false,
        enableMultiPhotoUpload: current.enableMultiPhotoUpload !== false,
        enableCustomText: current.enableCustomText !== false,
        enableReviews: current.enableReviews !== false,
        currencySymbol: current.currencySymbol || '₹',
        deliveryFee: Number(current.deliveryFee) || 100,
        freeDeliveryThreshold: Number(current.freeDeliveryThreshold) || 2000,
        announcementBanner: {
          enabled: Boolean(current.announcementBanner?.enabled),
          text: current.announcementBanner?.text || '✨ Limited Time: Handcrafted Italian Walnut finishes now available in all studio sizes!'
        },
        adminNotificationEmail: current.adminNotificationEmail || 'jaydeepsarkr@gmail.com',
        notifyAdminOnNewOrder: current.notifyAdminOnNewOrder !== false,
        orderIdPrefix: current.orderIdPrefix || 'PF'
      };
    },
    async handleSaveSettings() {
      this.saving = true;
      this.statusMessage = '';
      try {
        await this.updateSettings(this.form);
        this.statusType = 'success';
        this.statusMessage = 'Settings saved successfully! Changes are now active across the entire platform.';
      } catch (err) {
        this.statusType = 'error';
        this.statusMessage = err.message || 'Failed to save settings. Please try again.';
      } finally {
        this.saving = false;
      }
    },
    async confirmReset() {
      if (confirm('Are you sure you want to reset all studio settings to factory defaults?')) {
        this.saving = true;
        try {
          await this.resetSettings();
          this.loadSettingsIntoForm();
          this.statusType = 'success';
          this.statusMessage = 'All studio settings reset to factory defaults.';
        } catch (err) {
          this.statusType = 'error';
          this.statusMessage = 'Failed to reset settings.';
        } finally {
          this.saving = false;
        }
      }
    }
  }
};
